// Resolves a ball/brick overlap. `prevX/prevY` is the ball position at the
// START of the substep: the face hit is the one whose plane the ball's swept
// box crossed (entry face), which stays correct even when the ball ends up
// DEEP inside the brick (the min-penetration shortcut would then point at the
// wrong face and push the ball through the seam into the next row). When the
// previous position is also inside (defensive), fall back to the penetration
// rule, with the corner (equal penetration) case flipping both axes.
function bounceBall(ball, brick, prevX, prevY) {
  const hit = brickHit(ball, brick);
  if (!hit) return false;

  let face = null;
  if (prevY + ball.r <= brick.y && ball.y + ball.r > brick.y) face = 'top';
  else if (prevY - ball.r >= brick.y + brick.h && ball.y - ball.r < brick.y + brick.h) face = 'bottom';
  else if (prevX + ball.r <= brick.x && ball.x + ball.r > brick.x) face = 'left';
  else if (prevX - ball.r >= brick.x + brick.w && ball.x - ball.r < brick.x + brick.w) face = 'right';

  if (face === null) {
    // Previous position inside the brick: fall back to the penetration rule.
    if (Math.abs(hit.penX - hit.penY) <= 1e-6) {
      // Corner: flip both axes and push out diagonally.
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      if (ball.x < brick.x) ball.x -= hit.penX; else ball.x += hit.penX;
      if (ball.y < brick.y) ball.y -= hit.penY; else ball.y += hit.penY;
      return true;
    }
    if (hit.penX < hit.penY) {
      face = ball.x < brick.x ? 'left' : 'right';
    } else {
      face = ball.y < brick.y ? 'top' : 'bottom';
    }
  }

  switch (face) {
    case 'top':    ball.vy = -Math.abs(ball.vy); ball.y = brick.y - ball.r; break;
    case 'bottom': ball.vy = Math.abs(ball.vy);  ball.y = brick.y + brick.h + ball.r; break;
    case 'left':   ball.vx = -Math.abs(ball.vx); ball.x = brick.x - ball.r; break;
    case 'right':  ball.vx = Math.abs(ball.vx);  ball.x = brick.x + brick.w + ball.r; break;
  }
  return true;
