const STORAGE_KEY = 'neon.best';

// Max distance the ball may travel between two collision checks. Smaller than
// the ball diameter (14), the paddle band (12) and the brick height (20), so a
// fast ball can never jump over an obstacle between two detections (D5:
// tunneling starts at level 6, where one dt=0.05 step is 35.5 px > 34).
const MAX_SUBSTEP_DIST = 7;

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Brick collision and scoring moved here
// from the render loop so the logic is testable without a DOM (see #1/#2).
// The step is split into substeps short enough that the ball always overlaps
// an obstacle it crosses (no tunneling).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const travel = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(travel / MAX_SUBSTEP_DIST));
  const subDt = dt / substeps;

  for (let s = 0; s < substeps; s++) {
    const prevX = ball.x;
    const prevY = ball.y;
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: detect, bounce, kill and score in one pure pass.
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (bounceBall(ball, brick, prevX, prevY)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }

    // Exit through the bottom: ball lost (mid-step counts as lost).
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

