// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face is decided by `brickHit` in step() from the
// penetration depths.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce resolution (pure logic, used by step) --------------------

// Penetration depth of the ball into the brick on each axis, as the minimum of
// the two overlaps (the ball may be deep on one side). The face hit is the
// axis with the SMALLER penetration; if both are equal we are on a corner and
// BOTH axes must be resolved (see D6 in to_fix.md).
function brickHit(ball, brick) {
  const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
  if (penX <= 0 || penY <= 0) return null; // no overlap on one axis
  return { penX, penY };
}

// Applies a bounce: flips the velocity on the axis of the face hit and pushes
// the ball back out of the brick. `prevX/prevY` is the ball position at the
// START of the step: the face hit is the one whose plane the ball's swept box
// crossed (entry face). That stays correct even when the ball ends up DEEP
// inside the brick, where the penetration shortcut would point at the wrong
// face and push the ball through the seam into the next row (D4). When the
// previous position is also inside (defensive), fall back to the penetration
// rule, with the corner case (equal penetration) flipping both axes (D6).
function bounceBall(ball, brick, prevX, prevY) {
  const hit = brickHit(ball, brick);
  if (!hit) return false;

  let face = null;
  if (prevY + ball.r <= brick.y && ball.y + ball.r > brick.y) face = 'top';
  else if (prevY - ball.r >= brick.y + brick.h && ball.y - ball.r < brick.y + brick.h) face = 'bottom';
  else if (prevX + ball.r <= brick.x && ball.x + ball.r > brick.x) face = 'left';
  else if (prevX - ball.r >= brick.x + brick.w && ball.x - ball.r < brick.x + brick.w) face = 'right';

  if (face === null) {
    // Previous position also inside the brick: fall back to penetration.
    if (Math.abs(hit.penX - hit.penY) <= 1e-6) {
      // Corner: equal penetration on both axes -> both velocities flip (D6).
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      if (ball.x < brick.x) ball.x -= hit.penX;
      else ball.x += hit.penX;
      if (ball.y < brick.y) ball.y -= hit.penY;
      else ball.y += hit.penY;
      return true;
    }
    face = hit.penX < hit.penY
      ? (ball.x < brick.x ? 'left' : 'right')
      : (ball.y < brick.y ? 'top' : 'bottom');
  }

  switch (face) {
    case 'top': ball.vy = -Math.abs(ball.vy); ball.y = brick.y - ball.r; break;
    case 'bottom': ball.vy = Math.abs(ball.vy); ball.y = brick.y + brick.h + ball.r; break;
    case 'left': ball.vx = -Math.abs(ball.vx); ball.x = brick.x - ball.r; break;
    case 'right': ball.vx = Math.abs(ball.vx); ball.x = brick.x + brick.w + ball.r; break;
  }
  return true;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

