      // Renormalize so |v| stays at the level speed (D8).
      ball.vy = -Math.sqrt(ballSpeed(state.level) ** 2 - ball.vx ** 2);
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: detect, bounce, kill and score in one pure pass.
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (bounceBall(ball, brick, prevX, prevY)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
