// smoke.mjs — temporary gameplay smoke test (deleted after the playtest).
// Simulates real frames with a dumb paddle AI; checks the physics never
// produces NaN, out-of-field positions or unbounded speeds.

import { createState, step, makeBricks, ballSpeed, WIDTH, HEIGHT, PADDLE_W, PADDLE_H, BALL_R } from '../game/neon.js';

let state = createState(1);
state.running = true;
let frames = 0;
let lost = 0;
let hits = 0;
let maxSpeed = 0;
let minSpeed = Infinity;
let nan = 0;
let outOfField = 0;

const dts = [1 / 60, 1 / 60, 0.05, 1 / 120, 1 / 60, 1 / 144, 0.033, 0.05]; // mix of refresh rates incl. max dt

for (let i = 0; i < 60000; i++) {
  const dt = dts[i % dts.length];
  // dumb AI: keep the paddle under the ball
  state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, state.ball.x - state.paddle.w / 2));
  const wasAlive = state.bricks.filter((b) => b.alive).length;
  const lostThis = step(state, dt);
  if (lostThis) {
    lost += 1;
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      state = createState(state.level);
    } else {
      state.ball = createState(state.level).ball;
    }
  }
  const nowAlive = state.bricks.filter((b) => b.alive).length;
  if (nowAlive < wasAlive) hits += wasAlive - nowAlive;
  if (state.bricks.every((b) => !b.alive)) {
    state.level += 1;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
  }
  const b = state.ball;
  if (!Number.isFinite(b.x) || !Number.isFinite(b.y) || !Number.isFinite(b.vx) || !Number.isFinite(b.vy)) nan++;
  if (b.x - b.r < -1 || b.x + b.r > WIDTH + 1 || b.y - b.r < -1 || b.y + b.r > HEIGHT + 40) outOfField++;
  const speed = Math.hypot(b.vx, b.vy);
  if (speed > maxSpeed) maxSpeed = speed;
  if (speed < minSpeed) minSpeed = speed;
  frames++;
}

console.log(JSON.stringify({
  frames,
  bricksHit: hits,
  livesLost: lost,
  levelReached: state.level,
  nan,
  outOfField,
  minSpeed,
  maxSpeed,
  expected: ballSpeed(1),
}, null, 2));

